steps.script:
var d = tree.root.get_node_or_null("/root/AbilityChoiceDialog")
if d != null and d.visible:
	d.get_ok_button().pressed.emit()
	return true
return false

if not InputDeviceManager.is_pad_active():
	return "pad is not the active device - the card would be showing the mouse copy"
var t = tree.root.get_node_or_null("/root/TutorialOverlay/InstructorCard/Margin/VBox/BodyText")
if t == null:
	return "no card"
var s: String = str(t.text)
for needle in ["▲", "▼", "right-hand side", "savin' throws", "walk da highlight up into da queue"]:
	if not s.contains(needle):
		return "card never mentions '%s'" % needle
return "ok"

var d = tree.root.get_node_or_null("/root/Main/HUD_Right/VBoxContainer/ShootingScrollContainer/ShootingPanel/ResolutionDock")
if d == null or not d.visible:
	return "dock not up"
if str(d.state) != "queued":
	return "dock state is %s, arrows only exist while queued" % str(d.state)
var n: int = d.assignments.size()
if n < 2:
	return "only %d weapon(s) queued - nothing to re-order" % n
for i in range(n):
	var row = d.queue_box.get_node_or_null("QueueRow%d" % i)
	if row == null:
		return "no QueueRow%d" % i
	if row.get_node_or_null("Up%d" % i) == null or row.get_node_or_null("Down%d" % i) == null:
		return "row %d is missing its ▲▼ buttons" % i
var ids: Array = []
for a in d.assignments:
	ids.append(str(a.get("weapon_id", "?")))
tree.root.set_meta("t4_order_before", ids)
return "ok"

var d = tree.root.get_node("/root/Main/HUD_Right/VBoxContainer/ShootingScrollContainer/ShootingPanel/ResolutionDock")
var f = tree.root.get_viewport().gui_get_focus_owner()
if f == null:
	return "focus lost"
var want = "Up%d" % (d.assignments.size() - 1)
return "ok" if str(f.name) == want else "focus is on %s, expected %s" % [str(f.name), want]

var d = tree.root.get_node("/root/Main/HUD_Right/VBoxContainer/ShootingScrollContainer/ShootingPanel/ResolutionDock")
var before: Array = tree.root.get_meta("t4_order_before", [])
var after: Array = []
for a in d.assignments:
	after.append(str(a.get("weapon_id", "?")))
if before.size() != after.size():
	return "queue length changed"
var n = after.size()
if after[n - 1] != before[n - 2] or after[n - 2] != before[n - 1]:
	return "order unchanged: %s -> %s" % [str(before), str(after)]
for i in range(n - 2):
	if after[i] != before[i]:
		return "row %d moved too: %s -> %s" % [i, str(before), str(after)]
return "ok"

var f = tree.root.get_viewport().gui_get_focus_owner()
if f == null:
	return "focus dropped after the swap"
return "ok" if str(f.get_path()).contains("DockQueue") else "focus escaped to %s" % str(f.get_path())

var b = tree.root.get_node_or_null("/root/Main/AllocationGroupOverlay/Center/Panel/Row/DecisionCol/ResultPanel/DoneButton")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
return true

var b = tree.root.get_node_or_null("/root/Main/AllocationGroupOverlay/Center/Panel/Row/DecisionCol/ResultPanel/DoneButton")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
return true

var b = tree.root.get_node_or_null("/root/Main/AllocationGroupOverlay/Center/Panel/Row/DecisionCol/ResultPanel/DoneButton")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
return true

var b = tree.root.get_node_or_null("/root/Main/HUD_Right/VBoxContainer/ShootingScrollContainer/ShootingPanel/ResolutionDock/DockPrimaryButton")
if b != null and b.is_visible_in_tree() and not b.disabled:
	b.pressed.emit()
return true

var b = tree.root.get_node_or_null("/root/Main/HUD_Right/VBoxContainer/ShootingScrollContainer/ShootingPanel/ResolutionDock/DockPrimaryButton")
if b != null and b.is_visible_in_tree() and not b.disabled:
	b.pressed.emit()
return true
